#!/usr/bin/env bash
# Bundle item 186_labour_post_videos_30_w25_e24 (thread "Videos: Labour committee meetings", generated 23 Nov 2569)
# Labour after-meeting video(s), SELF-CONTAINED: mp4 / Thai vtt / poster are embedded below as base64 (the shared folder was
# over its cap, so nothing is read from committees/labour/media). 1080x1920, Thai voice + English subtitles burned in (one version).
# main committee meeting 30/2569 (12 Nov) after-meeting video v30, 4:26 ; welfare subcommittee meeting 25/2569 (18 Nov) after-meeting video sub-welfare-v25, 2:47 ; employment subcommittee meeting 24/2569 (18 Nov) after-meeting video sub-employment-v24, 3:14
# Surgical, same steps as item 134: adds the post video to the meeting's "media.videos" list after the existing pre video
# (pre first, then post; "video" field left as it is), CAPS track, meetings json, share pages (video_share.py CARD_BIG=1 +
# no_video_dl), home newest-4 list + Labour 2569 snapshot "v", then video_offload to the video repos.
# Idempotent; no git, no network. Needs $HUB ($BUILD defaults to archive/build).
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
L="$HUB/labour/2569"; SELF="$0"
test -f "$L/index.html" -a -f "$L/meetings.json" -a -f "$HUB/index.html" || { echo "186_labour_post_videos_30_w25_e24: pages missing" >&2; exit 1; }
mkdir -p "$L/media" "$L/img"
python3 - "$SELF" "$L" <<'PY'
import base64, hashlib, os, sys
src, L = sys.argv[1], sys.argv[2]
WANT = [('media/v30.mp4', '34a54c1a60aeb759dc8cf3e3f926cb5ff133d689a824644bd016a5aca6a1fc84', 10690538), ('media/v30.th.vtt', '027701af4309c63f120c1ffbeafc18c13a3ccc01d93824656afb08cdc192910f', 10681), ('img/poster30.jpg', '3349e3977c7a3d514fccc2b67077392f3b7eeed365c5c0d8403c1129e86a8c6f', 78413), ('media/sub-welfare-v25.mp4', 'd9287f277aaaf36d11532381c256c2fe38520b4c810d3c01a8160d5da88ebeae', 6968624), ('media/sub-welfare-v25.th.vtt', '9daaa6aaf6ec28330657b8895883712c77ac95b57a1f51987901da3ec892f394', 6482), ('img/poster-sub-welfare-25.jpg', 'f26d728057799f832f115d8d7e8b0d0a4f8f53ecc810afc1d3631fc9f4d8e35d', 98208), ('media/sub-employment-v24.mp4', 'b44015e622f44bb11f986a7475edf9bbb3e564fd3eb674507bfc373c3d58296d', 7900598), ('media/sub-employment-v24.th.vtt', '66894a32bc3f9b3a38a4ab954cd4efa5a9d077e55de71e502cb77cfd14edea63', 7576), ('img/poster-sub-employment-24.jpg', 'b1d94efeb5bf8e5ce83bc4dbcce6cc482a394cc36b15e476d4cdd4928a1d3042', 99410)]
cur, buf, got = None, [], {}
def flush():
    if cur: got[cur] = base64.b64decode(''.join(buf))
for line in open(src, encoding='ascii', errors='replace'):
    if line.startswith('__FILE__ '):
        flush(); cur, buf = line.split(' ', 1)[1].strip(), []
    elif cur and line.strip() and not line.startswith('#'):
        buf.append(line.strip())
flush()
for rel, sha, size in WANT:
    b = got.get(rel); assert b is not None, f'payload {rel} missing'
    assert len(b) == size and hashlib.sha256(b).hexdigest() == sha, f'payload {rel} damaged'
    p = os.path.join(L, rel)
    if not (os.path.exists(p) and open(p, 'rb').read() == b):
        open(p, 'wb').write(b)
print('payload ok:', ', '.join(r for r, _, _ in WANT))
PY
for v in v30:266 sub-welfare-v25:167 sub-employment-v24:194; do f=${v%%:*}; want=${v##*:}
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$L/media/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<1.5 else 1)" || { echo "186_labour_post_videos_30_w25_e24: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$L/media/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "186_labour_post_videos_30_w25_e24: $f size $wh" >&2; exit 1; }
  head -1 "$L/media/$f.th.vtt" | grep -q '^WEBVTT' || { echo "186_labour_post_videos_30_w25_e24: $f vtt header" >&2; exit 1; }
done
python3 - "$HUB" <<'PY'
import json, os, sys
HUB = sys.argv[1]; L = os.path.join(HUB, 'labour', '2569')
D = json.loads(r"""{
 "ITEMS": [
  {
   "page": "index.html",
   "json": "meetings.json",
   "key": "30|2026-11-12",
   "ck": "30",
   "entry": {
    "src": "media/v30.mp4",
    "poster": "img/poster30.jpg",
    "vtt": "media/v30.th.vtt",
    "kind": "post",
    "label": "วิดีโอสรุปผลการประชุม",
    "dur": "4:26",
    "cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
    "ck": "30"
   }
  },
  {
   "page": "sub-welfare.html",
   "json": "sub-welfare.json",
   "key": "25|2026-11-18",
   "ck": "welfare-25",
   "entry": {
    "src": "media/sub-welfare-v25.mp4",
    "poster": "img/poster-sub-welfare-25.jpg",
    "vtt": "media/sub-welfare-v25.th.vtt",
    "kind": "post",
    "label": "วิดีโอสรุปผลการประชุม",
    "dur": "2:47",
    "cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
    "ck": "welfare-25"
   }
  },
  {
   "page": "sub-employment.html",
   "json": "sub-employment.json",
   "key": "24|2026-11-18",
   "ck": "employment-24",
   "entry": {
    "src": "media/sub-employment-v24.mp4",
    "poster": "img/poster-sub-employment-24.jpg",
    "vtt": "media/sub-employment-v24.th.vtt",
    "kind": "post",
    "label": "วิดีโอสรุปผลการประชุม",
    "dur": "3:14",
    "cc": "เสียงบรรยายภาษาไทย มีคำบรรยายภาษาอังกฤษในวิดีโอ",
    "ck": "employment-24"
   }
  }
 ]
}""")
CMP = dict(ensure_ascii=False, separators=(',', ':'))
ser = lambda a: json.dumps(a, **CMP).replace('</', '<\\/')
changed = []
def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, HUB))
def jline(lines, prefix, dump):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f'{prefix} line not found once'
    line = lines[idx[0]]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(';')):]
    val = json.loads(body[:len(body) - len(tail)])
    assert prefix + dump(val) + tail == line, f'{prefix} line does not round-trip; not touching it'
    return idx[0], val, tail
def add(md, entry):
    e = dict(entry); e['size'] = os.path.getsize(os.path.join(L, e['src']))
    md = md or {}
    vids = [v for v in (md.get('videos') or ([md['video']] if md.get('video') else []))
            if v.get('ck') != e['ck'] and os.path.basename(v['src']) != os.path.basename(e['src'])]
    vids = [v for v in vids if v.get('kind') == 'pre'] + [e] + [v for v in vids if v.get('kind') != 'pre']
    md['videos'] = vids
    if not md.get('video'): md['video'] = vids[0]
    return md
for it in D['ITEMS']:
    p = os.path.join(L, it['page']); lines = open(p, encoding='utf-8').read().split('\n')
    i, arr, tail = jline(lines, 'const DATA=', ser)
    keys = {f"{m['n']}|{m['date']}": m for m in arr}
    assert it['key'] in keys, f"{it['page']}: meeting {it['key']} not on the page"
    keys[it['key']]['media'] = add(keys[it['key']].get('media'), it['entry'])
    lines[i] = 'const DATA=' + ser(arr) + tail
    i, caps, tail = jline(lines, 'const CAPS=', lambda a: json.dumps(a, ensure_ascii=False))
    caps[it['ck']] = open(os.path.join(L, it['entry']['vtt']), encoding='utf-8').read()
    lines[i] = 'const CAPS=' + json.dumps(caps, ensure_ascii=False) + tail
    put(p, '\n'.join(lines))
    p = os.path.join(L, it['json']); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f"{it['json']} does not round-trip; not touching it"
    mk = {f"{m['n']}|{m['date']}": m for m in ms}
    assert it['key'] in mk, f"{it['json']}: meeting {it['key']} missing"
    mk[it['key']]['media'] = add(mk[it['key']].get('media'), it['entry'])
    put(p, json.dumps(ms, ensure_ascii=False, indent=1))
# home page: newest-4 video list + Labour 2569 snapshot "v" (main committee meetings only)
ms = json.load(open(os.path.join(L, 'meetings.json'), encoding='utf-8'))
p = os.path.join(HUB, 'index.html'); t = open(p, encoding='utf-8').read(); dec = json.JSONDecoder()
mark = 'const HH = '
if t.count(mark) == 1:
    i = t.index(mark) + len(mark); hh, _ = dec.raw_decode(t[i:])
    old_s = ser(hh['videos']); assert t.count(old_s) == 1, 'home: video list text not found once'
    lab = []
    for m in ms:
        for v in (m.get('media') or {}).get('videos') or []:
            lab.append(dict(n=m['n'], date=m['date'], year=2569, who='กมธ.การแรงงาน', label=v.get('label') or 'วิดีโอสรุป',
                            dur=v.get('dur', ''), poster='labour/2569/' + v['poster'] if v.get('poster') else '',
                            headline='' if m.get('pending') else (m.get('headline') or ''), href=f"labour/2569/#read-{m['n']}"))
    seen = {(v['href'], v['poster']) for v in hh['videos']}
    vids = hh['videos'] + [v for v in lab if (v['href'], v['poster']) not in seen]
    vids.sort(key=lambda v: v['date'], reverse=True)
    t = t.replace(old_s, ser(vids[:4]), 1)
dm = 'const DATA = '; assert t.count(dm) == 1, 'home: DATA not found once'
j = t.index(dm) + len(dm); hub, _ = dec.raw_decode(t[j:])
nv = {(m['n'], m['date']): len((m.get('media') or {}).get('videos') or []) for m in ms}
for c in hub:
    if c.get('id') != 'labour': continue
    for y in c.get('years', []):
        if y.get('year') != 2569: continue
        for s in y.get('snap') or []:
            w = nv.get((s['n'], s['date']))
            if w is not None and s.get('v') != w:
                a = ser(s); s['v'] = w; b = ser(s)
                assert t.count(a) == 1, f'home: snapshot entry {s["n"]} not found once'
                t = t.replace(a, b, 1)
put(p, t)
print('186_labour_post_videos_30_w25_e24: changed', len(changed), 'text files:', ', '.join(changed) or 'none (already applied)')
PY
CARD_BIG=1 python3 "$BUILD/video_share.py" "$L" https://parliamentx.com/labour/2569 2569
python3 "$BUILD/no_video_dl.py" "$L/s"
python3 "$BUILD/no_video_dl.py" --check "$L"
for f in v-30 v-welfare-25 v-employment-24; do test -f "$L/s/$f.html" || { echo "186_labour_post_videos_30_w25_e24: share page s/$f.html missing" >&2; exit 1; }; done
VR=/mnt/project-files/archive/video_repos
if [ "${I97_TEST_NO_OFFLOAD:-}" = 1 ]; then echo "186_labour_post_videos_30_w25_e24: offload skipped (sandbox test only)"
else
  test -f $VR/ACTIVE || { echo "186_labour_post_videos_30_w25_e24: video repos not active; refusing to leave videos on the main site" >&2; exit 1; }
  grep -qxF '*.mp4' $HUB/.gitignore 2>/dev/null || { echo "186_labour_post_videos_30_w25_e24: $HUB/.gitignore has no *.mp4 line" >&2; exit 1; }
  python3 "$BUILD/video_offload.py" "$HUB" --report $VR/OFFLOAD_186_labour_post_videos_30_w25_e24.md
  python3 /mnt/project-files/archive/check/video_host_check.py "$HUB"
  if find "$L" -name '*.mp4' | grep -q .; then echo "186_labour_post_videos_30_w25_e24: mp4 still on the main site after offload" >&2; exit 1; fi
fi
echo "186_labour_post_videos_30_w25_e24 OK"
exit 0
